library ieee;
use ieee.std_logic_1164.all;
entity ss_button_input is
  generic (STAGES:positive range 2 to 64:=2;
    STABLE_CYCLES:positive range 1 to 2147483647:=500000;
    CLOCK_HZ:positive range 1 to 2147483647:=50000000;
    ACTIVE_LOW:natural range 0 to 1:=0; MODE:natural range 0 to 2:=0);
  port (clk,rst,d:in std_logic; q,pressed,released,pulse:out std_logic);
end entity;
architecture rtl of ss_button_input is
  signal sampled,level:std_logic;
begin
  synchronizer:entity work.ss_input_sync generic map(STAGES=>STAGES,RESET_LEVEL=>ACTIVE_LOW)
    port map(clk=>clk,rst=>rst,d=>d,q=>sampled);
  debounce:entity work.ss_input_debounce generic map(STABLE_CYCLES=>STABLE_CYCLES,CLOCK_HZ=>CLOCK_HZ,ACTIVE_LOW=>ACTIVE_LOW)
    port map(clk=>clk,rst=>rst,d=>sampled,q=>level,pressed=>open,released=>open);
  edges:entity work.ss_input_edge generic map(MODE=>MODE)
    port map(clk=>clk,rst=>rst,d=>level,rise=>pressed,fall=>released,pulse=>pulse);
  q<=level;
end architecture;

ss_input_sync.vhdl:
library ieee;
use ieee.std_logic_1164.all;
entity ss_input_sync is
  generic (STAGES:positive range 2 to 64:=2; RESET_LEVEL:natural range 0 to 1:=0);
  port (clk,rst,d:in std_logic; q:out std_logic);
end entity;
architecture rtl of ss_input_sync is
  constant levels:std_logic_vector(0 to 1):="01";
  signal pipe:std_logic_vector(STAGES-1 downto 0):=(others=>levels(RESET_LEVEL));
  attribute ASYNC_REG:string;
  attribute ASYNC_REG of pipe:signal is "TRUE";
begin
  q <= pipe(STAGES-1);
  process(clk) begin
    if rising_edge(clk) then
      if rst='1' then pipe <= (others=>levels(RESET_LEVEL));
      else pipe <= pipe(STAGES-2 downto 0) & d;
      end if;
    end if;
  end process;
end architecture;

ss_input_debounce.vhdl:
library ieee;
use ieee.std_logic_1164.all;
entity ss_input_debounce is
  generic (STABLE_CYCLES:positive range 1 to 2147483647:=500000; CLOCK_HZ:positive range 1 to 2147483647:=50000000; ACTIVE_LOW:natural range 0 to 1:=0);
  port (clk,rst,d:in std_logic; q,pressed,released:out std_logic);
end entity;
architecture rtl of ss_input_debounce is
  signal level:std_logic:='0';
  signal sample:std_logic;
  signal count:natural range 0 to STABLE_CYCLES-1:=0;
  signal press_event,release_event:std_logic:='0';
begin
  sample <= not d when ACTIVE_LOW=1 else d;
  q <= level; pressed <= press_event; released <= release_event;
  process(clk) begin
    if rising_edge(clk) then
      press_event <= '0'; release_event <= '0';
      if rst='1' then level <= '0'; count <= 0;
      elsif sample=level then count <= 0;
      elsif sample='0' or sample='1' then
        if count=STABLE_CYCLES-1 then
          level <= sample; count <= 0;
          if sample='1' then press_event <= '1'; else release_event <= '1'; end if;
        else count <= count+1;
        end if;
      else count <= 0;
      end if;
    end if;
  end process;
end architecture;

ss_input_edge.vhdl:
library ieee;
use ieee.std_logic_1164.all;
entity ss_input_edge is
  generic (MODE:natural range 0 to 2:=0);
  port (clk,rst,d:in std_logic; pulse,rise,fall:out std_logic);
end entity;
architecture rtl of ss_input_edge is
  signal previous,armed:std_logic:='0';
  signal event_selected,event_rise,event_fall:std_logic:='0';
begin
  pulse <= event_selected; rise <= event_rise; fall <= event_fall;
  process(clk) begin
    if rising_edge(clk) then
      event_selected <= '0'; event_rise <= '0'; event_fall <= '0';
      if rst='1' then previous <= '0'; armed <= '0';
      elsif d='0' or d='1' then
        if armed='1' then
          if previous='0' and d='1' then
            event_rise <= '1'; if MODE=0 or MODE=2 then event_selected <= '1'; end if;
          elsif previous='1' and d='0' then
            event_fall <= '1'; if MODE=1 or MODE=2 then event_selected <= '1'; end if;
          end if;
        end if;
        previous <= d; armed <= '1';
      end if;
    end if;
  end process;
end architecture;

