library ieee;
use ieee.std_logic_1164.all;
entity ss_tick is
  generic (DIVISOR:positive range 1 to 2147483647:=50000000);
  port (clk,rst,en:in std_logic; tick:out std_logic);
end entity;
architecture rtl of ss_tick is
  signal count:natural range 0 to DIVISOR-1:=0;
  signal event_tick:std_logic:='0';
begin
  tick <= event_tick;
  process(clk) begin
    if rising_edge(clk) then
      event_tick<='0';
      if rst='1' then count<=0;
      elsif en='1' then
        if count=DIVISOR-1 then count<=0; event_tick<='1';
        else count<=count+1; end if;
      end if;
    end if;
  end process;
end architecture;

ss_counter.vhdl:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
entity ss_counter is
  generic (WIDTH:positive range 1 to 64:=8; WRAP:natural range 0 to 1:=1);
  port (clk,rst,en,load,down:in std_logic;
    minimum,maximum,load_value:in std_logic_vector(WIDTH-1 downto 0);
    q:out std_logic_vector(WIDTH-1 downto 0);
    valid,terminal,wrapped:out std_logic);
end entity;
architecture rtl of ss_counter is
  signal value:unsigned(WIDTH-1 downto 0):=(others=>'0');
  signal wrap_event:std_logic:='0';
begin
  q <= std_logic_vector(value);
  valid <= '1' when unsigned(minimum)<=unsigned(maximum) and value>=unsigned(minimum) and value<=unsigned(maximum) else '0';
  terminal <= '1' when unsigned(minimum)<=unsigned(maximum) and
    ((down='0' and value=unsigned(maximum)) or (down='1' and value=unsigned(minimum))) else '0';
  wrapped <= wrap_event;
  process(clk)
    variable lo,hi,first:unsigned(WIDTH-1 downto 0);
  begin
    if rising_edge(clk) then
      lo:=unsigned(minimum); hi:=unsigned(maximum);
      first:=lo; if down='1' then first:=hi; end if;
      wrap_event<='0';
      if rst='1' then value<=first;
      elsif lo<=hi then
        if load='1' then
          if unsigned(load_value)<lo then value<=lo;
          elsif unsigned(load_value)>hi then value<=hi;
          else value<=unsigned(load_value); end if;
        elsif en='1' then
          if value<lo or value>hi then value<=first;
          elsif (down='0' and value=hi) or (down='1' and value=lo) then
            if WRAP=1 then value<=first; wrap_event<='1'; end if;
          elsif down='1' then value<=value-1;
          else value<=value+1; end if;
        end if;
      end if;
    end if;
  end process;
end architecture;

ss_bin_to_bcd.vhdl:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
entity ss_bin_to_bcd is
  generic (WIDTH:positive range 1 to 64:=8; DIGITS:positive range 1 to 20:=3; SIGNED_MODE:natural range 0 to 1:=0);
  port (d:in std_logic_vector(WIDTH-1 downto 0);
    bcd_lo:out std_logic_vector(63 downto 0); bcd_hi:out std_logic_vector(15 downto 0);
    negative,valid,overflow:out std_logic);
end entity;
architecture rtl of ss_bin_to_bcd is begin
  process(d)
    variable magnitude:unsigned(WIDTH-1 downto 0);
    variable digits_value:unsigned(79 downto 0);
    variable too_large:boolean;
  begin
    digits_value:=(others=>'0'); negative<='0'; valid<='0'; overflow<='0';
    if not is_x(d) then
      magnitude:=unsigned(d);
      if SIGNED_MODE=1 and d(WIDTH-1)='1' then magnitude:=unsigned(-signed(d)); negative<='1'; end if;
      for bit_index in WIDTH-1 downto 0 loop
        for digit in 0 to 19 loop
          if digits_value(4*digit+3 downto 4*digit)>=5 then
            digits_value(4*digit+3 downto 4*digit):=digits_value(4*digit+3 downto 4*digit)+3;
          end if;
        end loop;
        digits_value:=shift_left(digits_value,1); digits_value(0):=magnitude(bit_index);
      end loop;
      too_large:=false;
      for digit in DIGITS to 19 loop if digits_value(4*digit+3 downto 4*digit)/=0 then too_large:=true; end if; end loop;
      if too_large then overflow<='1'; else valid<='1'; end if;
    end if;
    bcd_lo<=std_logic_vector(digits_value(63 downto 0)); bcd_hi<=std_logic_vector(digits_value(79 downto 64));
  end process;
end architecture;
